// cmd_auth_v2.h — SAHOOL actuator command authentication, protocol v2 (R-C2).
//
// Pure logic, no Arduino types: it compiles in the sketch (mbedtls) and on a host with g++ and
// OpenSSL (test/test_cmd_auth_v2.cpp), so the device and the service are checked against one
// vectors file (test/cmd_auth_v2_vectors.json, generated by the Python reference
// services/actuator-service/cmd_signing_v2.py).
//
//   device_key = HMAC_SHA256(master, "sahool-cmd-key-v2|tenant|device")   (server side, hex)
//   sig        = HMAC_SHA256(device_key_bytes,
//                  "v2|tenant|device|field|id|cmd|duration_ms|iat|exp|ctr")
//   ack sig    = HMAC_SHA256(device_key_bytes, "v2ack|tenant|device|id|result|ctr")
//
// verify_command() checks, in this order (same order and reasons as reference_verify()):
//   provisioned -> v == 2 -> well-formed -> signature (constant time) -> tenant/device/field
//   binding -> ctr > last_ctr -> expiry (only if the clock is synced, never for CLOSE/OFF).
// The caller persists ctr as last_ctr BEFORE actuating.
#pragma once

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#if defined(ARDUINO) || defined(ESP_PLATFORM)
#include <mbedtls/md.h>
#else
#include <openssl/evp.h>
#include <openssl/hmac.h>
#endif

namespace cmdauth {

static const int kVersion = 2;
static const size_t kFieldMax = 63;   // identity buffers are 64 bytes (NVS)
static const size_t kIdMax = 96;
static const size_t kMsgMax = 512;

enum Result {
  ACCEPT = 0,
  REJ_NOT_PROVISIONED,
  REJ_VERSION,
  REJ_MALFORMED,
  REJ_SIGNATURE,
  REJ_BINDING,
  REJ_REPLAY,
  REJ_EXPIRED,
};

inline const char* reason(Result r) {
  switch (r) {
    case ACCEPT: return "accept";
    case REJ_NOT_PROVISIONED: return "not_provisioned";
    case REJ_VERSION: return "bad_version";
    case REJ_MALFORMED: return "malformed";
    case REJ_SIGNATURE: return "bad_signature";
    case REJ_BINDING: return "binding_mismatch";
    case REJ_REPLAY: return "replay";
    case REJ_EXPIRED: return "expired";
  }
  return "malformed";
}

// ── tiny HMAC abstraction ────────────────────────────────────────────────────
inline bool hmac_sha256(const uint8_t* key, size_t key_len, const uint8_t* msg, size_t msg_len,
                        uint8_t out[32]) {
#if defined(ARDUINO) || defined(ESP_PLATFORM)
  const mbedtls_md_info_t* info = mbedtls_md_info_from_type(MBEDTLS_MD_SHA256);
  return info != nullptr && mbedtls_md_hmac(info, key, key_len, msg, msg_len, out) == 0;
#else
  unsigned int len = 0;
  return HMAC(EVP_sha256(), key, (int)key_len, msg, msg_len, out, &len) != nullptr && len == 32;
#endif
}

inline void to_hex(const uint8_t* in, size_t n, char* out /* 2n+1 */) {
  static const char* d = "0123456789abcdef";
  for (size_t i = 0; i < n; i++) {
    out[2 * i] = d[in[i] >> 4];
    out[2 * i + 1] = d[in[i] & 0x0f];
  }
  out[2 * n] = '\0';
}

inline int hex_nibble(char c) {
  if (c >= '0' && c <= '9') return c - '0';
  if (c >= 'a' && c <= 'f') return c - 'a' + 10;
  if (c >= 'A' && c <= 'F') return c - 'A' + 10;
  return -1;
}

// 64 hex chars -> 32 bytes. Anything else is refused (SET_CMD_KEY validation).
inline bool parse_key_hex(const char* hex, uint8_t out[32]) {
  if (hex == nullptr || strlen(hex) != 64) return false;
  for (int i = 0; i < 32; i++) {
    int hi = hex_nibble(hex[2 * i]), lo = hex_nibble(hex[2 * i + 1]);
    if (hi < 0 || lo < 0) return false;
    out[i] = (uint8_t)((hi << 4) | lo);
  }
  return true;
}

// Constant-time comparison of two equal-length buffers.
inline bool ct_equal(const char* a, const char* b, size_t n) {
  uint8_t diff = 0;
  for (size_t i = 0; i < n; i++) diff |= (uint8_t)(a[i] ^ b[i]);
  return diff == 0;
}

// A signed field: non-empty, no '|' (the separator), bounded.
inline bool valid_field(const char* s, size_t max_len) {
  if (s == nullptr || s[0] == '\0') return false;
  size_t n = strlen(s);
  if (n > max_len) return false;
  return strchr(s, '|') == nullptr;
}

inline bool is_close(const char* cmd) {
  return cmd != nullptr && (strcmp(cmd, "CLOSE") == 0 || strcmp(cmd, "OFF") == 0);
}

inline bool is_wire_command(const char* cmd) {
  return cmd != nullptr && (strcmp(cmd, "OPEN") == 0 || strcmp(cmd, "ON") == 0 || is_close(cmd));
}

// ── what the device keeps in NVS ─────────────────────────────────────────────
struct Config {
  char tenant[kFieldMax + 1];
  char device[kFieldMax + 1];
  char field[kFieldMax + 1];
  uint8_t key[32];
  bool has_key;
  uint64_t last_ctr;
};

inline bool provisioned(const Config& c) {
  return c.has_key && c.tenant[0] != '\0' && c.device[0] != '\0' && c.field[0] != '\0';
}

// ── one parsed command (pointers into the JSON document) ─────────────────────
struct Command {
  bool has_v;
  long v;
  const char* id;
  const char* cmd;
  const char* tenant;
  const char* device;
  const char* field;
  const char* sig;
  bool numbers_ok;  // duration_ms/iat/exp/ctr present (iat/exp/ctr) and non-negative integers
  uint64_t duration_ms;
  uint64_t iat;
  uint64_t exp;
  uint64_t ctr;
};

inline int build_command_string(char* buf, size_t cap, const char* tenant, const char* device,
                                const char* field, const char* id, const char* cmd,
                                uint64_t duration_ms, uint64_t iat, uint64_t exp, uint64_t ctr) {
  return snprintf(buf, cap, "v2|%s|%s|%s|%s|%s|%llu|%llu|%llu|%llu", tenant, device, field, id,
                  cmd, (unsigned long long)duration_ms, (unsigned long long)iat,
                  (unsigned long long)exp, (unsigned long long)ctr);
}

inline bool sign_command_hex(const uint8_t key[32], const Command& m, char hex_out[65]) {
  char msg[kMsgMax];
  int n = build_command_string(msg, sizeof(msg), m.tenant, m.device, m.field, m.id, m.cmd,
                               m.duration_ms, m.iat, m.exp, m.ctr);
  if (n < 0 || n >= (int)sizeof(msg)) return false;  // truncated: never signed, never accepted
  uint8_t mac[32];
  if (!hmac_sha256(key, 32, (const uint8_t*)msg, (size_t)n, mac)) return false;
  to_hex(mac, 32, hex_out);
  return true;
}

inline Result verify_command(const Config& cfg, const Command& m, bool time_synced,
                             uint64_t now_ms) {
  if (!provisioned(cfg)) return REJ_NOT_PROVISIONED;
  if (!m.has_v || m.v != kVersion) return REJ_VERSION;
  if (!is_wire_command(m.cmd) || !m.numbers_ok || !valid_field(m.id, kIdMax) ||
      !valid_field(m.tenant, kFieldMax) || !valid_field(m.device, kFieldMax) ||
      !valid_field(m.field, kFieldMax) || m.sig == nullptr || m.sig[0] == '\0')
    return REJ_MALFORMED;
  char expected[65];
  if (!sign_command_hex(cfg.key, m, expected)) return REJ_MALFORMED;
  if (strlen(m.sig) != 64 || !ct_equal(expected, m.sig, 64)) return REJ_SIGNATURE;
  if (strcmp(m.tenant, cfg.tenant) != 0 || strcmp(m.device, cfg.device) != 0 ||
      strcmp(m.field, cfg.field) != 0)
    return REJ_BINDING;
  if (m.ctr <= cfg.last_ctr) return REJ_REPLAY;
  // Expiry only with a trusted clock, and never for the safe state.
  if (time_synced && !is_close(m.cmd) && now_ms > m.exp) return REJ_EXPIRED;
  return ACCEPT;
}

inline int build_ack_string(char* buf, size_t cap, const char* tenant, const char* device,
                            const char* id, const char* result, uint64_t ctr) {
  return snprintf(buf, cap, "v2ack|%s|%s|%s|%s|%llu", tenant, device, id, result,
                  (unsigned long long)ctr);
}

inline bool sign_ack_hex(const Config& cfg, const char* id, const char* result, uint64_t ctr,
                         char hex_out[65]) {
  if (!provisioned(cfg) || !valid_field(id, kIdMax) || !valid_field(result, kFieldMax))
    return false;
  char msg[kMsgMax];
  int n = build_ack_string(msg, sizeof(msg), cfg.tenant, cfg.device, id, result, ctr);
  if (n < 0 || n >= (int)sizeof(msg)) return false;
  uint8_t mac[32];
  if (!hmac_sha256(cfg.key, 32, (const uint8_t*)msg, (size_t)n, mac)) return false;
  to_hex(mac, 32, hex_out);
  return true;
}

// Server-side KDF, mirrored here only so the host test can check the vectors end to end.
inline bool derive_device_key_hex(const char* master, const char* tenant, const char* device,
                                  char hex_out[65]) {
  char msg[kMsgMax];
  int n = snprintf(msg, sizeof(msg), "sahool-cmd-key-v2|%s|%s", tenant, device);
  if (n < 0 || n >= (int)sizeof(msg)) return false;
  uint8_t mac[32];
  if (!hmac_sha256((const uint8_t*)master, strlen(master), (const uint8_t*)msg, (size_t)n, mac))
    return false;
  to_hex(mac, 32, hex_out);
  return true;
}

}  // namespace cmdauth
